// Best-effort HMAC verification. Django signs X-Signature = HMAC-SHA256(
// N8N_SHARED_SECRET, raw compact JSON body). NOTE: n8n's raw-body access varies
// by version, so this is observability-only and does NOT block delivery — enforce
// signatures with n8n native Header Auth or a network control in production.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET || '';
const items = $input.all();
let headers = {};
try { headers = ($input.first().json.headers) || {}; } catch (e) {}
const sig = headers['x-signature'] || headers['X-Signature'] || '';
let raw = '';
try {
  const j = $input.first().json;
  raw = (typeof j.body === 'string') ? j.body : JSON.stringify(j.body != null ? j.body : j);
} catch (e) { raw = ''; }
let valid = false;
try {
  if (secret && sig && raw) {
    const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
    valid = (expected.length === sig.length) &&
            crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
  }
} catch (e) { valid = false; }
return items.map(it => ({ json: Object.assign({}, it.json, { _signature_valid: valid }) }));

// Multilingual shipping/tracking email.
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};
const isTracking = (p.event === 'order.tracking_available');

const t = {
  en: { subjShip: `Your order ${d.order_number} has shipped`, subjTrack: `Tracking available for order ${d.order_number}`, hi: `Hi ${d.first_name || ''},`, shipped: 'Good news — your order is on its way!', tracking: 'Your tracking details are now available.', track_btn: 'Track your parcel', track_no: 'Tracking number', eta: 'Estimated delivery', days: 'business days', thanks: 'Thank you for shopping with Glitchy.' },
  it: { subjShip: `Il tuo ordine ${d.order_number} è stato spedito`, subjTrack: `Tracking disponibile per l’ordine ${d.order_number}`, hi: `Ciao ${d.first_name || ''},`, shipped: 'Buone notizie — il tuo ordine è in viaggio!', tracking: 'I dettagli di tracciamento sono ora disponibili.', track_btn: 'Traccia il pacco', track_no: 'Numero di tracking', eta: 'Consegna stimata', days: 'giorni lavorativi', thanks: 'Grazie per aver acquistato da Glitchy.' },
  fr: { subjShip: `Votre commande ${d.order_number} a été expédiée`, subjTrack: `Suivi disponible pour la commande ${d.order_number}`, hi: `Bonjour ${d.first_name || ''},`, shipped: 'Bonne nouvelle — votre commande est en route !', tracking: 'Les informations de suivi sont maintenant disponibles.', track_btn: 'Suivre mon colis', track_no: 'Numéro de suivi', eta: 'Livraison estimée', days: 'jours ouvrés', thanks: 'Merci d’avoir choisi Glitchy.' }
}[lang];
const L = t || { subjShip: `Your order ${d.order_number} has shipped`, subjTrack: `Tracking available for order ${d.order_number}`, hi: `Hi ${d.first_name || ''},`, shipped: 'Good news — your order is on its way!', tracking: 'Your tracking details are now available.', track_btn: 'Track your parcel', track_no: 'Tracking number', eta: 'Estimated delivery', days: 'business days', thanks: 'Thank you for shopping with Glitchy.' };

const subject = isTracking ? L.subjTrack : L.subjShip;
const lead = isTracking ? L.tracking : L.shipped;
const ship = d.shipping || {};
const eta = (ship.min_days != null && ship.max_days != null) ? `${ship.min_days}–${ship.max_days} ${L.days}` : '';
const btn = d.tracking_url ? `<p style="margin:18px 0"><a href="${d.tracking_url}" style="background:#111;color:#fff;padding:10px 18px;text-decoration:none;border-radius:6px;display:inline-block">${L.track_btn}</a></p>` : '';
const tno = d.tracking_number ? `<p><strong>${L.track_no}:</strong> ${d.tracking_number}</p>` : '';

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${subject}</h2>
<p>${L.hi}</p>
<p>${lead}</p>
${tno}
${btn}
${eta ? `<p><strong>${L.eta}:</strong> ${eta}</p>` : ''}
<p style="margin-top:20px;color:#666">${L.thanks}</p>
</div>`;

return [{ json: { to: p.recipient, subject, html } }];
